DROP TABLE IF EXISTS `bjdc_match`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bjdc_match` (
  `id` int NOT NULL AUTO_INCREMENT,
  `match_id` int NOT NULL,
  `issue` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `match_num` int NOT NULL,
  `match_num_str` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_week` varchar(10) COLLATE utf8mb4_general_ci NOT NULL,
  `match_time` datetime NOT NULL,
  `league_id` int DEFAULT NULL,
  `home_team_id` int DEFAULT NULL,
  `away_team_id` int DEFAULT NULL,
  `status` int DEFAULT NULL,
  `remark` text COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_bjdc_match_match_id` (`match_id`),
  KEY `league_id` (`league_id`),
  KEY `home_team_id` (`home_team_id`),
  KEY `away_team_id` (`away_team_id`),
  KEY `ix_bjdc_match_status` (`status`),
  KEY `ix_bjdc_match_issue` (`issue`),
  KEY `ix_bjdc_match_match_time` (`match_time`),
  CONSTRAINT `bjdc_match_ibfk_1` FOREIGN KEY (`league_id`) REFERENCES `league` (`id`),
  CONSTRAINT `bjdc_match_ibfk_2` FOREIGN KEY (`home_team_id`) REFERENCES `team` (`id`),
  CONSTRAINT `bjdc_match_ibfk_3` FOREIGN KEY (`away_team_id`) REFERENCES `team` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=536 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
