--
-- Table structure for table `tcbk_match`
--

DROP TABLE IF EXISTS `tcbk_match`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tcbk_match` (
  `id` int NOT NULL AUTO_INCREMENT,
  `match_id` int NOT NULL,
  `match_num` int DEFAULT NULL,
  `match_num_str` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_num_date` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_week` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_date` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_time` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `business_date` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `league_id` int DEFAULT NULL,
  `home_team_id` int DEFAULT NULL,
  `home_team_code` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `home_team_all_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `home_team_abb_name` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `home_team_rank` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `away_team_id` int DEFAULT NULL,
  `away_team_code` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `away_team_all_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `away_team_abb_name` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `away_team_rank` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `base_home_team_id` int DEFAULT NULL,
  `base_away_team_id` int DEFAULT NULL,
  `match_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `group_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `match_status` int DEFAULT NULL,
  `sell_status` int DEFAULT NULL,
  `is_hot` int DEFAULT NULL,
  `is_hide` int DEFAULT NULL,
  `betting_single` int DEFAULT NULL,
  `betting_all_up` int DEFAULT NULL,
  `back_color` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `remark` text COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_tcbk_match_match_id` (`match_id`),
  KEY `league_id` (`league_id`),
  CONSTRAINT `tcbk_match_ibfk_1` FOREIGN KEY (`league_id`) REFERENCES `tcbk_league` (`league_id`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

