DROP TABLE IF EXISTS `tcbk_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tcbk_result` (
  `id` int NOT NULL AUTO_INCREMENT,
  `match_id` int NOT NULL,
  `match_result_status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pool_status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `result_status` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `win_flag` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `half_score` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `full_score` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `home_score` int DEFAULT NULL,
  `away_score` int DEFAULT NULL,
  `score_diff` int DEFAULT NULL,
  `home_team` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `away_team` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `all_home_team` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `all_away_team` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `league_id` int DEFAULT NULL,
  `league_back_color` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `betting_single` int DEFAULT NULL,
  `is_cancel` int DEFAULT NULL,
  `spf_result` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `rfsf_result` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dxf_result` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sfc_result` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `match_id` (`match_id`),
  KEY `league_id` (`league_id`),
  CONSTRAINT `tcbk_result_ibfk_1` FOREIGN KEY (`match_id`) REFERENCES `tcbk_match` (`match_id`),
  CONSTRAINT `tcbk_result_ibfk_2` FOREIGN KEY (`league_id`) REFERENCES `tcbk_league` (`league_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

